import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = "Marek Zajac"
__copyright__ = "Copyright (C) 2021, Nokia"
__email__ = "marek.zajac@nokia.com"


class ScenarioUeStart(GenericRtg):
    """ScenarioUeStart command class."""

    def __init__(self, connection, mobile_session=None, parameters=None, prompt=None, newline_chars=None, runner=None):
        """
        Scenario ue start command.

        :param connection: moler connection to device, terminal when command is executed.
        :param mobile_session: mobile session to start
        :param parameters: optional keyword arguments
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ScenarioUeStart, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.mobile_session = mobile_session
        self.parameters = parameters
        self.processing_errors = []
        self.current_ret = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "scenario ue start"

        if self.mobile_session:
            cmd = f"{cmd} {self.mobile_session}"

        if self.parameters:
            for k, v in self.parameters.items():
                cmd += f" {k} {v}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_sucessfully_started(line)
                self._parse_param_processing_errors(line)
            except ParsingDone:
                pass
        return super(ScenarioUeStart, self).on_new_line(line, is_full_line)

    # Example line: Starting UE session: 1-attach
    _re_successfuly_started = re.compile(r"Starting UE session: (?P<SESSION_ID>\d+)-(?P<SESSION_NAME>.*)")

    def _parse_sucessfully_started(self, line):
        """
        Scenario ue start command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(ScenarioUeStart._re_successfuly_started, line):
            self.current_ret["SESSION_ID"] = self._regex_helper.group("SESSION_ID")
            self.current_ret["SESSION_NAME"] = self._regex_helper.group("SESSION_NAME")
            raise ParsingDone

    def _parse_param_processing_errors(self, line):
        """
        Scenario ue start command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self.processing_errors:
            if line.startswith("- "):
                self.processing_errors.append(line)
            else:
                self.set_exception(CommandFailure(self, "\n".join(self.processing_errors)))
            raise ParsingDone

        if "Parameters processsing error(s)" in line:
            self.processing_errors.append(line)
            raise ParsingDone


